#!/usr/bin/env node
/**
 * RNOH-New: Autolinking 代码生成脚本
 *
 * 扫描 node_modules 中符合 autolinking 条件的 npm 包，
 * 自动生成 C++ 和 ETS 侧的包注册表文件。
 *
 * 用法：
 *   node scripts/generate-autolinking.js --nodeModules=../node_modules
 *
 * 默认扫描目录：../node_modules
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// 生成文件顶部统一注释
const GENERATED_HEADER =
  '// Generated by @rnoh-new/react-native-harmony autolinking. DO NOT edit manually.\n';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const REACT_NATIVE_HARMONY_ROOT = path.resolve(__dirname, '..');

/**
 * 解析命令行参数
 * 支持 --nodeModules=<路径>，默认 ../node_modules
 * @returns {Object} 解析后的参数
 */
function parseArgs() {
  const args = process.argv.slice(2);
  const options = {
    nodeModules: path.resolve(REACT_NATIVE_HARMONY_ROOT, '../node_modules'),
  };
  for (const arg of args) {
    if (arg.startsWith('--nodeModules=')) {
      const value = arg.substring('--nodeModules='.length);
      options.nodeModules = path.isAbsolute(value)
        ? value
        : path.resolve(REACT_NATIVE_HARMONY_ROOT, value);
    } else if (arg === '--help' || arg === '-h') {
      printHelp();
      process.exit(0);
    }
  }
  return options;
}

/**
 * 打印帮助信息
 */
function printHelp() {
  console.log(`
RNOH-New Autolinking Generator

Usage:
  node scripts/generate-autolinking.js [options]

Options:
  --nodeModules=<path>  Path to node_modules directory (default: ../node_modules)
  --help, -h            Show this help message

Generated files:
  src/main/cpp/RNHAutolinking/PackageProvider.h
  src/main/cpp/RNHAutolinking/PackageProvider.cpp
  src/main/cpp/RNHAutolinking/autolinking.cmake
  src/main/ets/Autolinking/RNHPackageProvider.ets
`);
}

/**
 * 安全读取 JSON 文件
 * @param {string} filePath JSON 文件路径
 * @returns {Object|null} 解析后的对象，失败返回 null
 */
function readJsonSafe(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    return JSON.parse(content);
  } catch {
    return null;
  }
}

/**
 * 安全读取 JSON5 文件（oh-package.json5 支持）
 * 目前仅去除注释后按 JSON 解析，不支持完整 JSON5 语法
 * TODO: 后续可引入轻量 JSON5 解析器
 * @param {string} filePath JSON5 文件路径
 * @returns {Object|null} 解析后的对象，失败返回 null
 */
function readJson5Safe(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    // 去除单行注释 //...
    const noSingleLineComments = content.replace(/\/\/.*$/gm, '');
    // 去除多行注释 /*...*/
    const noComments = noSingleLineComments.replace(/\/\*[\s\S]*?\*\//g, '');
    return JSON.parse(noComments);
  } catch {
    return null;
  }
}

/**
 * 判断一个包是否符合 autolinking 条件
 * 条件 a) package.json 中含 "react-native-harmony" 字段
 * 条件 b) 包根目录存在 harmony/ 子目录且包含 oh-package.json5
 * @param {string} packageDir 包根目录
 * @returns {boolean}
 */
function isAutolinkablePackage(packageDir) {
  // 条件 a
  const packageJsonPath = path.join(packageDir, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    const pkg = readJsonSafe(packageJsonPath);
    if (pkg && pkg['react-native-harmony']) {
      return true;
    }
  }

  // 条件 b
  const harmonyDir = path.join(packageDir, 'harmony');
  if (fs.existsSync(harmonyDir) && fs.statSync(harmonyDir).isDirectory()) {
    const ohPackageJson5Path = path.join(harmonyDir, 'oh-package.json5');
    if (fs.existsSync(ohPackageJson5Path)) {
      return true;
    }
  }

  return false;
}

/**
 * 提取包的 autolinking 元数据
 * @param {string} packageDir 包根目录
 * @returns {Object|null} 元数据对象
 */
function extractPackageMetadata(packageDir) {
  const packageJsonPath = path.join(packageDir, 'package.json');
  const pkg = fs.existsSync(packageJsonPath)
    ? readJsonSafe(packageJsonPath) || {}
    : {};

  // 优先读取 react-native-harmony 字段中的配置
  const rnHarmonyConfig = pkg['react-native-harmony'] || {};

  // 确定 harmony 模块路径
  let harmonyPath = rnHarmonyConfig.harmonyPath || 'harmony';
  if (!path.isAbsolute(harmonyPath)) {
    harmonyPath = path.relative(
      REACT_NATIVE_HARMONY_ROOT,
      path.join(packageDir, harmonyPath)
    );
  }
  // 统一使用正斜杠（跨平台、CMake/C++ include 路径兼容）
  harmonyPath = normalizePath(harmonyPath);

  // 读取 oh-package.json5 获取模块名和版本
  const ohPackageJson5Path = path.join(packageDir, 'harmony', 'oh-package.json5');
  const ohPackage = readJson5Safe(ohPackageJson5Path) || {};

  const name = rnHarmonyConfig.name || ohPackage.name || pkg.name || '';
  const version = rnHarmonyConfig.version || ohPackage.version || pkg.version || '0.0.0';

  // C++ 库名，默认根据 npm 包名转换
  const defaultCppLibraryName = toPascalCase(pkg.name || 'Unknown') + 'Package';
  const cppLibraryName = rnHarmonyConfig.cppLibraryName || defaultCppLibraryName;

  // C++ Package 类名，默认根据库名推断
  const cppPackageClassName =
    rnHarmonyConfig.cppPackageClassName ||
    (cppLibraryName.endsWith('Package')
      ? cppLibraryName
      : cppLibraryName + 'Package');

  // C++ 头文件路径
  let cppHeaderPath =
    rnHarmonyConfig.cppHeaderPath ||
    `${harmonyPath}/src/main/cpp/${cppPackageClassName}.h`;
  cppHeaderPath = normalizePath(cppHeaderPath);

  // ETS Package 类名
  const etsPackageClassName =
    rnHarmonyConfig.etsPackageClassName || cppPackageClassName;

  // ETS 导入路径
  const etsImportPath =
    rnHarmonyConfig.etsImportPath ||
    `${harmonyPath}/src/main/ets/${etsPackageClassName}`;

  return {
    npmName: pkg.name || '',
    name,
    version,
    harmonyPath,
    cppLibraryName,
    cppPackageClassName,
    cppHeaderPath,
    etsPackageClassName,
    etsImportPath,
  };
}

/**
 * 将路径分隔符统一为正斜杠
 * @param {string} filePath 文件路径
 * @returns {string} 正斜杠路径
 */
function normalizePath(filePath) {
  if (!filePath) return filePath;
  return filePath.replace(/\\/g, '/');
}

/**
 * 将短横线/点分隔字符串转为 PascalCase
 * 例如 @rnoh-new/vector-icons -> RNOHNewVectorIcons
 * @param {string} str 输入字符串
 * @returns {string} PascalCase 字符串
 */
function toPascalCase(str) {
  if (!str) return 'Unknown';
  return str
    .replace(/[@/\.]/g, '-') // @ scope 分隔符和路径分隔符统一为 -
    .split('-')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

/**
 * 扫描 node_modules 中所有可 autolink 的包
 * @param {string} nodeModulesPath node_modules 路径
 * @returns {Object[]} 包元数据数组
 */
function scanAutolinkablePackages(nodeModulesPath) {
  if (!fs.existsSync(nodeModulesPath) || !fs.statSync(nodeModulesPath).isDirectory()) {
    console.warn(`[autolinking] node_modules not found: ${nodeModulesPath}`);
    return [];
  }

  const packages = [];
  const entries = fs.readdirSync(nodeModulesPath, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;

    const packageDir = path.join(nodeModulesPath, entry.name);

    if (entry.name.startsWith('@')) {
      // scoped package: @scope/pkg
      const scopeEntries = fs.readdirSync(packageDir, { withFileTypes: true });
      for (const scopeEntry of scopeEntries) {
        if (!scopeEntry.isDirectory()) continue;
        const scopedPackageDir = path.join(packageDir, scopeEntry.name);
        if (isAutolinkablePackage(scopedPackageDir)) {
          const metadata = extractPackageMetadata(scopedPackageDir);
          if (metadata.name) {
            packages.push(metadata);
          }
        }
      }
    } else {
      if (isAutolinkablePackage(packageDir)) {
        const metadata = extractPackageMetadata(packageDir);
        if (metadata.name) {
          packages.push(metadata);
        }
      }
    }
  }

  return packages;
}

/**
 * 生成 C++ PackageProvider.h 文件内容
 * @param {Object[]} packages 包元数据数组
 * @returns {string}
 */
function generateCppHeader(packages) {
  const includes = packages
    .map((pkg) => `#include "${pkg.cppHeaderPath}"`)
    .join('\n');

  return `${GENERATED_HEADER}/**
 * RNOH-New: Autolinked Package Provider
 *
 * 自动生成的包注册表头文件。
 * 提供 createAutolinkedPackages 和 autolink_libraries 两个入口。
 */

#pragma once

#include <memory>
#include <vector>
#include "../RNH/RNHPackage.h"

namespace rnoh_new {

// 前向声明
struct RNHPackageContext;

${includes || '// 暂无 autolink 的包'}

/**
 * 创建所有自动链接的 Package 实例
 * @param ctx 包上下文
 * @return Package 实例列表
 */
std::vector<std::shared_ptr<RNHPackage>> createAutolinkedPackages(
    const RNHPackageContext& ctx);

} // namespace rnoh_new

/**
 * CMake 宏：为 target 自动链接所有扫描到的库
 * @param target CMake 目标名
 */
#define autolink_libraries(target) \\
${packages.length === 0 ? '    // 暂无 autolink 的库' : packages.map((pkg) => `    target_link_libraries(target PUBLIC ${pkg.cppLibraryName})`).join(' \\\n')}
`;
}

/**
 * 生成 C++ PackageProvider.cpp 文件内容
 * @param {Object[]} packages 包元数据数组
 * @returns {string}
 */
function generateCppSource(packages) {
  const factoryEntries = packages
    .map(
      (pkg) => `    packages.push_back(
        std::make_shared<${pkg.cppPackageClassName}>(ctx)
    );`
    )
    .join('\n');

  return `${GENERATED_HEADER}/**
 * RNOH-New: Autolinked Package Provider Implementation
 *
 * 自动生成的包注册表实现。
 */

#include "PackageProvider.h"

namespace rnoh_new {

std::vector<std::shared_ptr<RNHPackage>> createAutolinkedPackages(
    const RNHPackageContext& ctx) {
    std::vector<std::shared_ptr<RNHPackage>> packages;
${factoryEntries || '    // 暂无 autolink 的包'}
    return packages;
}

} // namespace rnoh_new
`;
}

/**
 * 生成 autolinking.cmake 文件内容
 * @param {Object[]} packages 包元数据数组
 * @returns {string}
 */
function generateCMake(packages) {
  const libraryAdds = packages
    .map(
      (pkg) => `# ${pkg.npmName} v${pkg.version}
add_subdirectory(
    \${CMAKE_CURRENT_SOURCE_DIR}/${pkg.harmonyPath}/src/main/cpp
    \${CMAKE_CURRENT_BINARY_DIR}/${toPascalCase(pkg.npmName || pkg.name)}_cpp
)`
    )
    .join('\n\n');

  return `${GENERATED_HEADER}# RNOH-New: Autolinking CMake
#
# 自动生成的 CMake 子目录包含文件。
# 在根 CMakeLists.txt 中 include 本文件即可自动添加所有 autolink 库。

${packages.length === 0 ? '# 暂无 autolink 的库' : libraryAdds}

# autolink_libraries 宏定义在 PackageProvider.h 中
`;
}

/**
 * 生成 ETS RNHPackageProvider.ets 文件内容
 * @param {Object[]} packages 包元数据数组
 * @returns {string}
 */
function generateEtsProvider(packages) {
  const imports = packages
    .map((pkg) => `import { ${pkg.etsPackageClassName} } from '${pkg.etsImportPath}';`)
    .join('\n');

  const factoryEntries = packages
    .map((pkg) => `    packages.push(new ${pkg.etsPackageClassName}(ctx));`)
    .join('\n');

  return `${GENERATED_HEADER}/**
 * RNOH-New: Autolinked Package Provider (ETS)
 *
 * 自动生成的 ETS 侧包注册表。
 */

import type { RNHPackageContext, RNHPackage } from '../RNH/RNHPackage';
${imports || '// 暂无 autolink 的包'}

/**
 * 创建所有自动链接的 ETS Package 实例
 * @param ctx 包上下文
 * @return Package 实例数组
 */
export function createAutolinkedPackages(ctx: RNHPackageContext): RNHPackage[] {
    const packages: RNHPackage[] = [];
${factoryEntries || '    // 暂无 autolink 的包'}
    return packages;
}
`;
}

/**
 * 确保目录存在
 * @param {string} dirPath 目录路径
 */
function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

/**
 * 写入生成文件
 * @param {string} filePath 目标文件路径
 * @param {string} content 文件内容
 */
function writeGeneratedFile(filePath, content) {
  ensureDir(path.dirname(filePath));
  fs.writeFileSync(filePath, content, 'utf8');
  console.log(`[autolinking] Generated: ${filePath}`);
}

/**
 * 主函数
 */
function main() {
  const args = parseArgs();
  console.log(`[autolinking] Scanning: ${args.nodeModules}`);

  const packages = scanAutolinkablePackages(args.nodeModules);
  console.log(`[autolinking] Found ${packages.length} autolinkable package(s)`);
  for (const pkg of packages) {
    console.log(`  - ${pkg.npmName} -> ${pkg.name} (${pkg.cppPackageClassName})`);
  }

  // 输出路径
  const cppAutolinkingDir = path.join(
    REACT_NATIVE_HARMONY_ROOT,
    'src/main/cpp/RNHAutolinking'
  );
  const etsAutolinkingDir = path.join(
    REACT_NATIVE_HARMONY_ROOT,
    'src/main/ets/Autolinking'
  );

  // 生成 C++ 侧文件
  writeGeneratedFile(
    path.join(cppAutolinkingDir, 'PackageProvider.h'),
    generateCppHeader(packages)
  );
  writeGeneratedFile(
    path.join(cppAutolinkingDir, 'PackageProvider.cpp'),
    generateCppSource(packages)
  );
  writeGeneratedFile(
    path.join(cppAutolinkingDir, 'autolinking.cmake'),
    generateCMake(packages)
  );

  // 生成 ETS 侧文件
  writeGeneratedFile(
    path.join(etsAutolinkingDir, 'RNHPackageProvider.ets'),
    generateEtsProvider(packages)
  );

  console.log('[autolinking] Done.');
}

main();
